mapper.select:
SELECT s.id, s.user_id, s.title, s.status, s.last_active_at, s.deleted_at,
       s.created_at, s.updated_at, sm.model_label, sm.model_source,
       skb.kb_id, kb.name AS kb_name
FROM sessions s
LEFT JOIN session_models sm ON sm.session_id = s.id
LEFT JOIN session_knowledge_bases skb ON skb.session_id = s.id
LEFT JOIN knowledge_bases kb ON kb.id = skb.kb_id
WHERE s.user_id = #{userId}
  AND s.status = #{status}

  AND (s.last_active_at < #{beforeActiveAt}
       OR (s.last_active_at = #{beforeActiveAt} AND s.id < #{beforeId}))

ORDER BY s.last_active_at DESC, s.id DESC
LIMIT #{limit}

mapper.update:
UPDATE sessions
SET title = #{title}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'active'

UPDATE sessions
SET title = #{title}
WHERE id = #{id}
  AND title = #{defaultTitle}

UPDATE sessions
SET last_active_at = #{lastActiveAt}
WHERE id = #{id}
  AND status = 'active'

UPDATE sessions
SET status = 'archived',
    deleted_at = #{deletedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'active'

UPDATE sessions
SET status = 'active',
    deleted_at = NULL,
    last_active_at = #{lastActiveAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'archived'

mapper.delete:
DELETE FROM sessions
WHERE id = #{id}
  AND user_id = #{userId}
